const items = $('SC Get Plants Sheet').all();
const lines = items.map(i => {
  const p = i.json;
  return `[${p.plant_id}] ${p.plant_species||''} | ${p.location||''} | ${p.status||''} | เน€เธฃเธดเนเธก ${p.start_date||''} | stage: ${p.growth_stage_th||p.growth_stage||'-'}`;
});
return [{ json: { plants_string: lines.length>0 ? 'USER PLANTS:\n'+lines.join('\n') : 'USER PLANTS: (เธขเธฑเธเนเธกเนเธกเธตเนเธเธฅเธ)' } }];

const text = ($('SC Edit Fields').item.json.text || '').trim();

// เธชเธฃเนเธฒเธเธงเธฑเธเธ—เธตเนเนเธฅเธฐเน€เธงเธฅเธฒเธเธฑเธเธเธธเธเธฑเธ (Bangkok Time) เธฃเธนเธเนเธเธ YYYY-MM-DD HH:mm:ss
const now = new Date();
const offset = 7 * 60; // UTC+7
const bangkokTime = new Date(now.getTime() + (offset + now.getTimezoneOffset()) * 60000);
const today = bangkokTime.toISOString().replace('T', ' ').substring(0, 19);

const cmdMatch = text.match(/^\/([^\s]+)(?:\s+(.*))?$/s);
let command = 'ask', rawArgs = text;

if (cmdMatch) {
  const cmd = cmdMatch[1].toLowerCase();
  rawArgs = (cmdMatch[2] || '').trim();
  if (['เธเธฅเธนเธ','plant','create'].includes(cmd))                 command = 'create';
  else if (['เนเธเน','เนเธเนเนเธ','update','edit'].includes(cmd))      command = 'update';
  else if (['เธ–เธฒเธก','ask','เธเธณเธ–เธฒเธก'].includes(cmd))                command = 'ask';
  else if (['เธฅเธ','delete','remove'].includes(cmd))             command = 'delete';
  else if (['เธฃเธฒเธเธฒ','price'].includes(cmd))                     command = 'price';
  else if (['เนเธเธฅเธ','myplants','plot'].includes(cmd))           command = 'myplants';
  else if (['help','เธเนเธงเธข','start'].includes(cmd))              command = 'help';
  else if (['เธขเธทเธเธขเธฑเธเนเธเน','confirmupdate','confirm_update'].includes(cmd))   command = 'confirm_update';
  else if (['เธขเธทเธเธขเธฑเธเธฅเธ','confirmdelete','confirm_delete'].includes(cmd))    command = 'confirm_delete';
  else if (['เธขเธเน€เธฅเธดเธ','cancel'].includes(cmd))                  command = 'cancel';
  else                                                         command = 'unknown';
} else {
  command = 'ask';
}

let cmd_rice_type='', cmd_location='', cmd_area_rai=1, cmd_start_date = today; // เนเธเนเธเนเธฒ today (Now) เน€เธเนเธเธเนเธฒเน€เธฃเธดเนเธกเธ•เนเธ
let cmd_plant_id='', tmp=rawArgs;

if (command === 'create') {
  // เธ•เธฃเธงเธเธชเธญเธเธเธณเธเธงเธเนเธฃเน
  const areaM = tmp.match(/(\d+(?:\.\d+)?)\s*เนเธฃเน/);
  if (areaM) { cmd_area_rai=parseFloat(areaM[1]); tmp=tmp.replace(areaM[0],'').trim(); }

  // เธ•เธฃเธงเธเธชเธญเธเธงเธฑเธเธ—เธตเน (เธ–เนเธฒเธเธนเนเนเธเนเธเธดเธกเธเนเธงเธฑเธเธ—เธตเนเธกเธฒเน€เธญเธ เน€เธเนเธ 2026-01-01 เนเธซเนเนเธเนเธเนเธฒเธ—เธตเนเธเธนเนเนเธเนเธเธดเธกเธเน)
  const dateM = tmp.match(/(\d{4}-\d{2}-\d{2})/);
  if (dateM) { 
    cmd_start_date=dateM[1]; 
    tmp=tmp.replace(dateM[0],'').trim(); 
  }

  const parts = tmp.split(/\s+/);
  if (parts.length>=2) { cmd_rice_type=parts[0]; cmd_location=parts.slice(1).join(' '); }
  else if (parts.length===1) cmd_rice_type=parts[0];
}

if (['update','delete','confirm_update','confirm_delete'].includes(command)) {
  const pidM = rawArgs.match(/PLANT-[\w-]+/i);
  if (pidM) cmd_plant_id=pidM[0];
}

const plantsStr = $input.first().json.plants_string || '';

return [{ json: {
  command, 
  cmd_rice_type, 
  cmd_location, 
  cmd_area_rai, 
  cmd_start_date, // เธเธฐเน€เธเนเธเน€เธงเธฅเธฒเธเธฑเธเธเธธเธเธฑเธเธ—เธฑเธเธ—เธตเธ–เนเธฒเนเธกเนเนเธ”เนเธฃเธฐเธเธธเธงเธฑเธเธ—เธตเนเธกเธฒ
  cmd_plant_id, 
  cmd_raw_args: rawArgs || text, 
  plants_string: plantsStr,
  original_text: text,
  generated_at: today
} }];

function clean(t){ return (t||'').replace(/\*\*/g,'').replace(/\*/g,'').replace(/_/g,'').replace(/`/g,'').replace(/\[/g,'').replace(/\]/g,'').replace(/\(/g,'').replace(/\)/g,''); }
const raw = $input.first().json.output || '';
let cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
  if (parsed.data) {
    parsed.data.area_rai ??= 1;
    parsed.data.water_frequency_days ??= 3;
    parsed.data.status ??= 'Active';
    parsed.data.last_watered_date ??= null;
    parsed.data.fertilizer ??= null;
    delete parsed.data.growth_stage;
    delete parsed.data.growth_stage_th;
  }
  if (parsed.reply_message) parsed.reply_message = clean(parsed.reply_message);
} catch(e) {
  parsed = { action:'none', reply_message:clean(raw), data:{}, sheet_name:'none' };
}
return [{ json: { parsed } }];

