}
if (others.length) { msg+=`\n๐“ เธญเธทเนเธเน:\n`; others.forEach(i=>{ msg+=`โ€ข [${i.json.plant_id}] ${i.json.plant_species} | ${i.json.status}\n`; }); }
msg += `\nเธเธดเธกเธเน /เธ–เธฒเธก เธซเธฃเธทเธญ /เนเธเน เน€เธเธทเนเธญเธเธฑเธ”เธเธฒเธฃเนเธเธฅเธเนเธ”เนเน€เธฅเธขเธเธฐเธเธฐ ๐’`;
