const items = $input.all();

// เน€เธญเธฒ item เนเธฃเธเน€เธเนเธ editFields
const editFields = items[0]?.json || {};
const userId = String(editFields.user_id || '');

const users = items
  .filter(i => i.json?.user_id != null)
  .map(i => i.json);

