// =========================
// ๐งน Clean function (safe)
// =========================
function clean(t) {
  return (t || '')
    .replace(/\\n/g, '\n')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .replace(/_/g, '')
    .replace(/\[/g, '')     
    .replace(/\]/g, '')
    .replace(/\(/g, '')
    .replace(/\)/g, '');
}

// =========================
// ๐“ฅ เธฃเธฑเธ raw output เธเธฒเธ AI
// =========================
const raw = $input.first().json.output || '';

// =========================
// ๐งฝ Clean wrapper markdown
// =========================
let cleaned = raw
  .replace(/```json/gi, '') // remove ```json
  .replace(/```/g, '')      // remove ```
  .trim();

// =========================
// ๐ง  Parse JSON
// =========================
let parsed;

try {
  parsed = JSON.parse(cleaned);

  // โ… sanitize reply_message
  if (parsed.reply_message) {
    parsed.reply_message = clean(parsed.reply_message);
  }

  // โ… default fallback fields
  parsed.action = parsed.action || 'none';
  parsed.sheet_name = parsed.sheet_name || 'none';
  parsed.data = parsed.data || {};

} catch (e) {
  // =========================
  // ๐จ Fallback (AI เธ•เธญเธเนเธกเนเน€เธเนเธ JSON)
  // =========================
  parsed = {
    action: 'none',
    reply_message: clean(raw),
    sheet_name: 'none',
    data: {},
    _error: 'invalid_json',
  };
}

// =========================
// ๐“ค Output
// =========================
return [
  {
    json: {
      parsed
    }
  }
];

// เธเธฑเธเธเนเธเธฑเธเธฅเนเธฒเธเธญเธฑเธเธเธฃเธฐเธเธดเน€เธจเธฉ
function clean(t) { 
  return (t || '').replace(/\*\*/g, '').replace(/\*/g, '').replace(/_/g, '').replace(/`/g, '').replace(/\[/g, '').replace(/\]/g, '').replace(/\(/g, '').replace(/\)/g, ''); 
}

// เธ”เธถเธเธเนเธฒเธเธฒเธ output (เธฃเธญเธเธฃเธฑเธ Agent)
const raw = $input.first().json.output || "";
let parsed;

try {
  // เธเธขเธฒเธขเธฒเธกเธซเธฒ JSON เธ เธฒเธขเนเธเธเนเธญเธเธงเธฒเธก (เน€เธเธทเนเธญ AI เธเธดเธกเธเนเธเนเธญเธเธงเธฒเธกเธญเธทเนเธเธเธเธกเธฒ)
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  let cleaned = jsonMatch ? jsonMatch[0] : raw;

  parsed = JSON.parse(cleaned);

  if (parsed.reply_message) {
    parsed.reply_message = clean(parsed.reply_message);
  }
} catch (e) {
  // เธซเธฒเธ Parse เนเธกเนเนเธ”เน เนเธซเนเน€เธญเธฒเธเนเธญเธเธงเธฒเธกเธ”เธดเธเธกเธฒเนเธชเธ”เธเน€เธเนเธ reply_message เนเธ—เธ undefined
  parsed = { 
    action: 'none', 
    reply_message: clean(raw) || "เธเธญเธญเธ เธฑเธขเธเนเธฐ เนเธเนเธชเนเธกเนเน€เธเนเธฒเนเธเธเธณเธชเธฑเนเธเธฅเธ เธเธฃเธธเธ“เธฒเธฅเธญเธเนเธซเธกเนเธญเธตเธเธเธฃเธฑเนเธเธเธฐเธเธฐ", 
    data: {}, 
    sheet_name: 'none' 
  };
}

return [{ json: { parsed } }];

const items = $input.all();
const data = items.map(i => i.json);

// =========================
// ๐”ฅ Helper (เธชเนเธงเธเธเนเธงเธขเธเธณเธเธงเธ“)
// =========================

function formatItem(i) {
  // เน€เธเธฅเธตเนเธขเธเธเธฒเธเธเธตเธ” (-) เน€เธเนเธ Bullet เนเธฅเธฐเน€เธเธดเนเธกเธเธณเนเธซเนเธ”เธนเน€เธเนเธเธเธฃเธฐเนเธขเธเธเธญเธเน€เธฅเนเธฒ
  return `โ€ข ${i.name}: เธเธฃเธฐเธกเธฒเธ“ ${i.price_range} ${i.unit}`;
}

function findMax(arr) {
  return arr.reduce((max, cur) => cur.price_avg > max.price_avg ? cur : max, arr[0]);
}

function findMin(arr) {
  return arr.reduce((min, cur) => cur.price_avg < min.price_avg ? cur : min, arr[0]);
}

// =========================
// ๐”ฅ เนเธขเธเธซเธกเธงเธ”เธซเธกเธนเนเธเนเธฒเธง
// =========================

const riceWhite = data.filter(i => i.name.includes("เธเนเธฒเธงเธเธฒเธง"));
const riceSticky = data.filter(i => i.name.includes("เน€เธซเธเธตเธขเธง"));
const riceJasmine = data.filter(i => i.name.includes("เธซเธญเธก"));

// =========================
// ๐”ฅ เน€เธฃเธดเนเธกเธชเธฃเนเธฒเธเธเนเธญเธเธงเธฒเธก
// =========================

let message = `เธชเธงเธฑเธชเธ”เธตเธเนเธฒ เธเธตเนเน เธเนเธญเธเน เน€เธเธฉเธ•เธฃเธเธฃ ๐พ๐’\n`;
message += `๐“ เธงเธฑเธเธเธตเน "เนเธเนเธช" เน€เธญเธฒเธญเธฑเธเน€เธ”เธ•เธฃเธฒเธเธฒเธเนเธฒเธงเธฅเนเธฒเธชเธธเธ”เธกเธฒเธเธฒเธเธเธฑเธเธเนเธฒ\n\n`;

// =========================
// ๐พ เธเนเธฒเธงเธเธฒเธง
// =========================

if (riceWhite.length) {
  message += `๐ เธเธฅเธธเนเธกเธเนเธฒเธงเธเธฒเธง:\n`;
  riceWhite.forEach(i => {
    message += formatItem(i) + "\n";
  });

  const max = findMax(riceWhite);
  const min = findMin(riceWhite);

  message += `\nโญ เธฃเธฒเธเธฒเธ”เธตเธ—เธตเนเธชเธธเธ”: ${max.name} (เน€เธเธฅเธตเนเธข ${max.price_avg} เธเธฒเธ—)\n`;
  message += `๐“ เธฃเธฒเธเธฒเน€เธฃเธดเนเธกเธ•เนเธ: ${min.name} (เน€เธเธฅเธตเนเธข ${min.price_avg} เธเธฒเธ—)\n\n`;
}

// =========================
// ๐พ เธเนเธฒเธงเน€เธซเธเธตเธขเธง
// =========================

