// ===== helper =====
function formatDate(d) {
  return d.toLocaleDateString("en-CA", { timeZone: "Asia/Bangkok" });
}

function normalizeLocation(loc) {
  if (!loc) return null;
  if (loc === "เธเธฃเธธเธเน€เธ—เธ") return "เธเธฃเธธเธเน€เธ—เธเธกเธซเธฒเธเธเธฃ";
  return loc;
}

// normalize เนเธซเนเน€เธเนเธ date (เธ•เธฑเธ”เน€เธงเธฅเธฒ + fix timezone)
function toBangkokDateOnly(dateStr) {
  const d = new Date(dateStr);
  return new Date(d.toLocaleDateString("en-US", { timeZone: "Asia/Bangkok" }));
}

// ===== STEP 1: prepare date =====
const now = new Date();
const today = new Date(now.toLocaleDateString("en-US", { timeZone: "Asia/Bangkok" }));

const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);

const todayTime = today.getTime();
const tomorrowTime = tomorrow.getTime();

// ===== STEP 2: process =====
const grouped = {};

for (const item of items) {
  const plant = item.json;

  // ===== VALIDATION =====
  if (!plant.status || plant.status.toLowerCase() !== "active") continue;

  // โ ๏ธ เธ–เนเธฒ field เธเธตเนเนเธกเนเธกเธตเนเธ data เธเธธเธ“ โ’ comment เธญเธญเธเนเธ”เน
  if (plant.environment && plant.environment !== "Outdoor") continue;

  const freq = Number(plant.water_frequency_days);
  if (!freq || isNaN(freq)) continue;

  const location = normalizeLocation(plant.location);
  if (!location) continue;

  // ===== FIX เธชเธณเธเธฑเธ =====
  const baseDate = plant.last_watered_date || plant.start_date;
  if (!baseDate) continue;

  const last = toBangkokDateOnly(baseDate);

  // ===== CALCULATE =====
  const next = new Date(last);
  next.setDate(next.getDate() + freq);

  const nextTime = next.getTime();

  // เน€เธญเธฒเน€เธเธเธฒเธฐ overdue / today / tomorrow
  if (nextTime > tomorrowTime) continue;

  // ===== STATUS =====
  let watering_status = "future";

  if (nextTime < todayTime) {
    watering_status = "overdue";
  } else if (nextTime === todayTime) {
    watering_status = "today";
  } else if (nextTime === tomorrowTime) {
    watering_status = "tomorrow";
  }

  const userId = plant.user_id;

  // ===== GROUP =====
  if (!grouped[location]) grouped[location] = {};
  if (!grouped[location][userId]) grouped[location][userId] = [];

  grouped[location][userId].push({
    plant_id: plant.plant_id,
    plant_species: plant.plant_species,
    next_watering_date: formatDate(next),
    watering_status,
    growth_stage: plant.growth_stage || "Unknown",
    growth_stage_th: plant.growth_stage_th || "เนเธกเนเธ—เธฃเธฒเธ",
    start_date: plant.start_date || null
  });
}

// ===== STEP 3: convert =====
const result = Object.keys(grouped).map(location => ({
  json: {
    location,
    users: grouped[location]
  }
}));

// ===== EMPTY CASE =====
if (result.length === 0) {
  return [{
