      status: "no_data",
      message: "เนเธกเนเธกเธตเธเธทเธเธ—เธตเนเธ•เนเธญเธเธฃเธ”เธเนเธณ (เธฃเธงเธก overdue / today / tomorrow)"
    }
  }];
}

return result;

