        forecasts_7day: forecasts,
        plant_set: new Set(), plant_details: []
      };
    }
    for (const p of users[userId]) {
      grouped[key].plant_set.add(p.plant_species);
      grouped[key].plant_details.push(p);
    }
  }
}

