function getGrowthStage(startDateStr) {
  if (!startDateStr) return { stage: 'unknown', daysOld: null };
  const d = Math.floor((Date.now() - new Date(startDateStr)) / 86400000);
  if (d < 0)   return { stage: 'pre_plant',   daysOld: d };
  if (d <= 14) return { stage: 'germination', daysOld: d };
  if (d <= 30) return { stage: 'seedling',    daysOld: d };
  if (d <= 60) return { stage: 'tillering',   daysOld: d };
  if (d <= 80) return { stage: 'booting',     daysOld: d };
  if (d <= 95) return { stage: 'heading',     daysOld: d };
  if (d <= 120) return { stage: 'ripening',   daysOld: d };
  return { stage: 'harvest', daysOld: d };
}

