  if (stage==='harvest') a.push({ level:'เธเธฒเธเธเธฅเธฒเธ', msg:'เธ–เธถเธเธฃเธฐเธขเธฐเน€เธเนเธเน€เธเธตเนเธขเธง เธเธงเธฃเธฃเธตเธเน€เธเนเธ!' });
  return a;
}

const items = $input.all();
const result = [];

for (const item of items) {
  const d = item.json;
  if (d.status === 'no_data') { result.push(item); continue; }

  const forecasts = (d.forecasts_7day || []);
  const plants    = d.plant_details || [];

  // เธเธณเธเธงเธ“ stage เธเธญเธเนเธ•เนเธฅเธฐเนเธเธฅเธ
  const stageInfoList = plants.map(p => {
    const { stage, daysOld } = getGrowthStage(p.start_date);
    return { plant_id:p.plant_id, rice_type:p.plant_species||p.rice_type, stage, daysOld, stageLabel:STAGE_TH[stage]||stage };
  });

  // เธงเธดเน€เธเธฃเธฒเธฐเธซเนเธ—เธฑเนเธ 7 เธงเธฑเธ
  const dayRows = [];
  const allAlerts = [];

  for (const fc of forecasts) {
    const dateStr = (fc.time||'').split('T')[0];
    const rain    = fc.data?.rain ?? 0;
    const tcMax   = fc.data?.tc_max ?? null;
    const tcMin   = fc.data?.tc_min ?? null;
    const rh      = fc.data?.rh ?? null;
    const isRaining = rain >= 1;
    const rl      = getRainLevel(rain);

    // alerts เธ—เธธเธเนเธเธฅเธเนเธเธงเธฑเธเธเธตเน
    const dayAlerts = [];
    for (const s of stageInfoList) {
      dayAlerts.push(...alertsForDay(s.stage, rain, isRaining));
    }

    const maxDayScore = dayAlerts.reduce((m,a)=>Math.max(m,riskScore(a.level)),0);
    const dayRiskLevel = scoreToLevel(maxDayScore);

    let icon = 'โ€๏ธ';
    if (rain > 50) icon = 'โ๏ธ';
    else if (rain > 20) icon = '๐ง๏ธ';
    else if (rain > 5)  icon = '๐ฆ๏ธ';
    else if (rain > 0)  icon = 'โ…';

    const advice = dayAlerts.length > 0
      ? dayAlerts.sort((a,b)=>riskScore(b.level)-riskScore(a.level))[0].msg
      : (isRaining ? 'เธเธ”เธฃเธ”เธเนเธณ เธเธเธ•เธ' : 'เธเธฅเธญเธ”เธ เธฑเธขเธ”เธต');

    dayRows.push({ dateStr, icon, tcMax, tcMin, rh, rain, rainLevel:rl, riskLevel:dayRiskLevel, advice });
    allAlerts.push(...dayAlerts);
  }

  // เธชเธฃเนเธฒเธเธเนเธญเธเธงเธฒเธก 7 เธงเธฑเธ
  const loc = d.location || '';
  let msg = `๐พ เธเธขเธฒเธเธฃเธ“เน 7 เธงเธฑเธ โ€” ${loc}\n`;
  msg += `(เธญเธฑเธเน€เธ”เธ•เธ—เธธเธเน€เธเนเธฒ 07:00 เธ.)\n\n`;

  for (const r of dayRows) {
    const tmp = (r.tcMax!=null&&r.tcMin!=null) ? ` ${r.tcMin}-${r.tcMax}ยฐC` : '';
    const humid = r.rh!=null ? ` เธเธงเธฒเธกเธเธทเนเธ ${r.rh}%` : '';
    msg += `${r.icon} ${r.dateStr}${tmp}${humid} เธเธ ${r.rain}mm (${r.rainLevel})\n`;
    msg += `   ${riskIcon(r.riskLevel)} ${r.riskLevel} โ€” ${r.advice}\n`;
  }

  // เธชเธฃเธธเธเนเธเธฅเธ
  if (stageInfoList.length > 0) {
    msg += `\n๐“ เธชเธ–เธฒเธเธฐเนเธเธฅเธเธเธญเธเธเธธเธ“:\n`;
    for (const s of stageInfoList) {
      msg += `๐ฑ ${s.rice_type||'เธเนเธฒเธง'}: ${s.stageLabel}`;
      if (s.daysOld!=null) msg += ` (เธญเธฒเธขเธธ ${s.daysOld} เธงเธฑเธ)`;
      msg += '\n';
    }
  }

  // เธซเธฒ worst day
  const worst = [...dayRows].sort((a,b)=>riskScore(b.riskLevel)-riskScore(a.riskLevel))[0];
  if (worst && riskScore(worst.riskLevel) >= 2) {
    msg += `\nโ ๏ธ เนเธเนเธชเนเธเธฐเธเธณ: เธฃเธฐเธงเธฑเธเธเนเธงเธ ${worst.dateStr} โ€” ${worst.advice}\n`;
  }

  msg += `\nเนเธเนเธชเน€เธเนเธเธเธณเธฅเธฑเธเนเธเนเธซเนเธเธฐเธเธฐ ๐’`;

  const overallRisk = scoreToLevel(allAlerts.reduce((m,a)=>Math.max(m,riskScore(a.level)),0));

  result.push({
    json: { ...d, message: msg, risk_level: overallRisk, stage_info: stageInfoList, day_forecast: dayRows }
  });
}

return result;

// โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•
//  ๐พ STAGE AUTO-UPDATE โ€” เธเธณเธเธงเธ“ growth_stage เธญเธฑเธ•เนเธเธกเธฑเธ•เธด
//
//  Input : item เธเธฒเธ Send a text message2 (1 item เธ•เนเธญ 1 user)
//          เธเธถเนเธเธกเธต plant_details: [ { plant_id, plant_species,
//                                    start_date, end_date,
//                                    status, ... } ]
//
//  Output: flatten เน€เธเนเธ 1 item เธ•เนเธญ 1 plant_id
//          เธเธฃเนเธญเธก field เธ—เธตเนเธ•เนเธญเธ update เธฅเธ Sheet:
//            - plant_id       (เนเธเน match)
//            - growth_stage   (เธเธณเธเธงเธ“เธเธฒเธ start_date)
//            - status         (Active / Harvested / Overdue)
//            - days_old       (เธญเธฒเธขเธธเนเธเธงเธฑเธ)
// โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•

// โ”€โ”€ map เธเธฃเธฐเน€เธ เธ—เธเนเธฒเธง โ’ เธเนเธงเธเน€เธงเธฅเธฒเธชเธธเธ (เธงเธฑเธ) โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€
// เธญเนเธฒเธเธญเธดเธเธเธฒเธเธเนเธญเธกเธนเธฅเธเนเธฒเธงเธ—เธตเนเธฃเธฐเธเธธ (เธเนเธฒเธงเธเธฒเธง/เน€เธซเธเธตเธขเธง/เธซเธญเธกเธกเธฐเธฅเธด/เธซเธญเธกเธเธ—เธธเธก)
function getRiceDuration(species) {
  const s = (species || '').toLowerCase();
  if (s.includes('เธซเธญเธกเธกเธฐเธฅเธด'))  return { min: 105, max: 130 }; // เธเนเธฒเธงเธเธฒเธเธต เธญเธฒเธขเธธเธขเธฒเธง
  if (s.includes('เธเธ—เธธเธก'))      return { min: 90,  max: 110 }; // เธเธ.เธเธ—เธธเธก เธญเธฒเธขเธธเธชเธฑเนเธ-เธเธฅเธฒเธ
  if (s.includes('เธเธ'))        return { min: 90,  max: 115 };
  if (s.includes('เน€เธซเธเธตเธขเธง'))    return { min: 110, max: 130 };
  return { min: 90, max: 120 }; // เธเนเธฒเธงเธเธฒเธงเธ—เธฑเนเธงเนเธ / default
}

// โ”€โ”€ เธเธณเธเธงเธ“ growth stage เธเธฒเธ start_date + rice type โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€
function getGrowthStage(startDateStr, endDateStr, species) {
  if (!startDateStr) return { stage: 'Unknown', status: 'Active', daysOld: null };

  const now   = new Date();
  const start = new Date(startDateStr);
  const daysOld = Math.floor((now - start) / (1000 * 60 * 60 * 24));

  // เธ–เนเธฒเธกเธต end_date เนเธฅเธฐเน€เธฅเธขเนเธฅเนเธง โ’ Harvested เธซเธฃเธทเธญ Overdue
  if (endDateStr) {
    const end = new Date(endDateStr);
    const daysToEnd = Math.floor((end - now) / (1000 * 60 * 60 * 24));
    if (daysToEnd < -14) {
      return { stage: 'Overdue', status: 'Overdue', daysOld };
    }
  }

  const { max } = getRiceDuration(species);

  if (daysOld < 0)    return { stage: 'Pre-Plant',   status: 'Active', daysOld };
  if (daysOld <= 14)  return { stage: 'Germination', status: 'Active', daysOld };
  if (daysOld <= 30)  return { stage: 'Seedling',    status: 'Active', daysOld };
  if (daysOld <= 60)  return { stage: 'Tillering',   status: 'Active', daysOld };
  if (daysOld <= Math.round(max * 0.65))
                      return { stage: 'Booting',     status: 'Active', daysOld };
  if (daysOld <= Math.round(max * 0.80))
                      return { stage: 'Heading',     status: 'Active', daysOld };
  if (daysOld <= max) return { stage: 'Ripening',    status: 'Active', daysOld };

  // เน€เธเธดเธ max โ’ เธ–เธถเธเน€เธงเธฅเธฒเน€เธเนเธเน€เธเธตเนเธขเธง
  return { stage: 'Ready to Harvest', status: 'Harvested', daysOld };
}

// โ”€โ”€ label เธ เธฒเธฉเธฒเนเธ—เธข โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€
