  'Tillering':        'เธฃเธฐเธขเธฐเนเธ•เธเธเธญ',
  'Booting':          'เธฃเธฐเธขเธฐเธ•เธฑเนเธเธ—เนเธญเธ',
  'Heading':          'เธฃเธฐเธขเธฐเธญเธญเธเธฃเธงเธ',
  'Ripening':         'เธฃเธฐเธขเธฐเธชเธธเธเนเธเน',
  'Ready to Harvest': 'เธเธฃเนเธญเธกเน€เธเนเธเน€เธเธตเนเธขเธง',
  'Harvested':        'เน€เธเนเธเน€เธเธตเนเธขเธงเนเธฅเนเธง',
  'Overdue':          'เน€เธเธดเธเธเธณเธซเธเธ”',
  'Unknown':          'เนเธกเนเธ—เธฃเธฒเธ',
};

// โ”€โ”€ Bangkok date string โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€โ”€
function todayBKK() {
  return new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Bangkok' });
}

// โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•
// MAIN
// โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•โ•
const items = $input.all();
const result = [];

for (const item of items) {
  const d = item.json;

  // plant_details เธกเธฒเธเธฒเธ Risk Calculator (เธเธถเนเธเธฃเธฑเธเธ•เนเธญเธเธฒเธ Code in JavaScript8)
  const plants = d.plant_details || [];

  if (plants.length === 0) continue; // เนเธกเนเธกเธตเนเธเธฅเธ โ’ เธเนเธฒเธก

  for (const plant of plants) {
    const pid     = plant.plant_id;
    const species = plant.plant_species || plant.rice_type || '';
    const startD  = plant.start_date   || null;
    const endD    = plant.end_date     || null;
    const currStatus = (plant.status   || 'Active');

    // เธเนเธฒเธกเนเธเธฅเธเธ—เธตเนเธ–เธนเธ Harvested/Removed เนเธเนเธฅเนเธง (user เธญเธฑเธเน€เธ”เธ•เน€เธญเธ)
    if (['Harvested', 'Removed', 'Inactive'].includes(currStatus)) continue;

    const { stage, status: newStatus, daysOld } = getGrowthStage(startD, endD, species);
    const stageTH = STAGE_TH[stage] || stage;

    result.push({
      json: {
        plant_id:     pid,
        growth_stage: stage,
        growth_stage_th: stageTH,
        status:       newStatus,
        days_old:     daysOld,
        updated_at:   todayBKK(),
        // pass-through เธ—เธตเนเธ•เนเธญเธเนเธเนเนเธ Sheet (match key)
        _species:     species,
        _user_id:     d.user_id || plant.user_id || '',
      }
    });
  }
}

// เธ–เนเธฒเนเธกเนเธกเธตเนเธเธฅเธ Active เน€เธฅเธข โ’ เธชเนเธ dummy เน€เธเธทเนเธญเนเธกเนเนเธซเน flow เธซเธขเธธเธ”
if (result.length === 0) {
