// 1. เธฃเธฑเธเธเนเธญเธกเธนเธฅเนเธฅเธฐเนเธเธฅเธเน€เธเนเธ JSON 
// (เน€เธเนเธ typeof เน€เธเธทเนเธญเนเธเธเธฃเธ“เธตเธ—เธตเน n8n เธเธฑเนเธ rawData เน€เธเนเธ Object เธกเธฒเนเธซเนเนเธฅเนเธง เธเธฐเนเธ”เนเนเธกเน Error)
const rawData = $input.first().json.data;
const parsedJson = typeof rawData === 'string' ? JSON.parse(rawData) : rawData;
// เธฃเธญเธเธฃเธฑเธเนเธเธฃเธเธชเธฃเนเธฒเธเน€เธเธทเนเธญเธงเนเธฒ parsedJson เน€เธเนเธ array เนเธ”เธขเธ•เธฃเธ เธซเธฃเธทเธญเธเนเธญเธเธญเธขเธนเนเนเธ .data
const items = parsedJson.data || parsedJson;

// 2. Keyword เธชเธดเธเธเนเธฒเธขเธญเธ”เธเธดเธขเธก
const popularKeywords = [
  "เธเนเธฒเธงเธเธฒเธง",
  "เธเนเธฒเธงเธซเธญเธกเธกเธฐเธฅเธด",
  "เธเนเธฒเธงเธซเธญเธกเธเธ—เธธเธกเธเธฒเธเธต", // เน€เธเธดเนเธกเธเนเธฒเธงเธซเธญเธกเธเธ—เธธเธกเธฏ (เธ—เธฒเธเน€เธฅเธทเธญเธเธขเธญเธ”เธฎเธดเธ•)
  "เธเนเธฒเธงเธชเธฒเธฃเน€เธซเธเธตเธขเธง"     // เนเธเนเธเธฒเธ "เธเนเธฒเธงเน€เธซเธเธตเธขเธง" เน€เธเธทเนเธญเนเธซเนเธ•เธฃเธเธเธฑเธเธเธทเนเธญเนเธ Data
];

// 3. Filter + Format
const result = items
  .filter(item => {
    const name = item.NAME;

    // เธ•เนเธญเธเธกเธต keyword เธเธฅเธธเนเธกเธชเธดเธเธเนเธฒเธขเธญเธ”เธเธดเธขเธก
    const isPopular = popularKeywords.some(k => name.includes(k));

    // เธ•เธฑเธ”เธเธญเธเธ—เธตเนเนเธกเนเนเธเนเธญเธญเธ (Noise)
    const isNoise = name.includes("เธเธฅเธฒเธขเธเนเธฒเธง") || 
