const headers = $input.first().json.headers;

// เธซเธฒ set-cookie header (เธญเธฒเธเน€เธเนเธ array เธซเธฃเธทเธญ string)
let setCookieHeader = headers['set-cookie'] || headers['Set-Cookie'] || '';

// เธ–เนเธฒเน€เธเนเธ array เนเธซเน join เธเธฑเธ
if (Array.isArray(setCookieHeader)) {
  setCookieHeader = setCookieHeader.join('; ');
}

// เนเธเธฐเน€เธญเธฒเนเธเน key=value เธ•เธฑเธ”เธเธงเธ path, expires, HttpOnly เธ—เธดเนเธ
const cookieParts = [];
const rawCookies = Array.isArray(headers['set-cookie'] || headers['Set-Cookie'])
  ? (headers['set-cookie'] || headers['Set-Cookie'])
  : [setCookieHeader];

for (const c of rawCookies) {
  const part = c.split(';')[0].trim();
  if (part) cookieParts.push(part);
}

const cookieString = cookieParts.join('; ');

return [{ json: { cookie: cookieString } }];
